    expect(getResponseValue(notificationsPost1Response, "data.subject"), 'subject').toBe("Deployment finished");
    expect(getResponseValue(notificationsPost1Response, "data.message"), 'message').toBe("Build 4821 deployed to production");
    expect(getResponseValue(notificationsPost1Response, "data.status"), 'status').toBe("inbox");
