    expect(getResponseValue(notificationsNotificationsGet1Response, "data.id"), 'id').toBe(getResponseValue(notificationsPost1Response, "data.id"));
    expect(getResponseValue(notificationsNotificationsGet1Response, "data.subject"), 'subject').toBe("Deployment finished");
    expect(getResponseValue(notificationsNotificationsGet1Response, "data.status"), 'status').toBe("read");

